// Builds supabase/seed/*.sql from the JSON sources in supabase/data/.
//   node scripts/build-seed.mjs
// supabase/data/museums.json lists the museums; supabase/data/<museum>/<language>.json holds
// one catalog each (categories + works). Run the generated files in the Supabase SQL editor
// after supabase/catalog.sql: 00_museums.sql first, then any of the per-museum files.
// Every file is an upsert, so it is safe to re-run after editing the data.
import { mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const dataDir = join(root, "supabase", "data");
const seedDir = join(root, "supabase", "seed");

const read = (p) => JSON.parse(readFileSync(p, "utf8"));

/** A jsonb literal. Dollar-quoted, so no escaping is needed as long as the tag is absent from the data. */
function jsonb(value) {
  const text = JSON.stringify(value);
  if (text.includes("$seed$")) throw new Error("data contains the $seed$ dollar-quote tag");
  return `$seed$${text}$seed$::jsonb`;
}

rmSync(seedDir, { recursive: true, force: true });
mkdirSync(seedDir, { recursive: true });

const museums = read(join(dataDir, "museums.json"));
writeFileSync(
  join(seedDir, "00_museums.sql"),
  `-- Generated by scripts/build-seed.mjs from supabase/data/museums.json. Do not edit.
insert into public.museums (id, name, subtitle, lat, lng, city, country, continent, icon, sort_order)
select id, name, subtitle, lat, lng, city, country, continent, icon, sort_order
from jsonb_populate_recordset(null::public.museums, ${jsonb(museums)})
on conflict (id) do update set
  name = excluded.name, subtitle = excluded.subtitle, lat = excluded.lat, lng = excluded.lng,
  city = excluded.city, country = excluded.country, continent = excluded.continent,
  icon = excluded.icon, sort_order = excluded.sort_order;
`,
);

const CHUNK_BYTES = 350_000; // target size of one works insert
const SPLIT_ABOVE = 800_000; // a museum's file is split when it would be larger than this
let total = 0;
for (const entry of readdirSync(dataDir, { withFileTypes: true })) {
  if (!entry.isDirectory()) continue;
  const header = `-- Generated by scripts/build-seed.mjs from supabase/data/${entry.name}/. Do not edit.\n`;
  let sql = "";
  const parts = [];
  for (const file of readdirSync(join(dataDir, entry.name)).sort()) {
    const c = read(join(dataDir, entry.name, file));
    const { id: museumId, language, name, location, textCredit } = c.museum;
    const works = c.works
      .filter((w) => w.listed !== false)
      .map((w, i) => ({
        museum_id: museumId,
        language,
        id: w.id,
        position: i,
        title: w.title,
        category: w.category ?? null,
        subtitle: w.subtitle ?? null,
        artist: w.artist ?? null,
        facts: w.facts ?? [],
        object_url: w.objectUrl ?? null,
        image: w.image ?? null,
        guide: w.guide,
      }));
    total += works.length;
    const catalog = [
      { museum_id: museumId, language, museum_name: name, location, text_credit: textCredit ?? null, categories: c.categories },
    ];
    sql += `
insert into public.catalogs (museum_id, language, museum_name, location, text_credit, categories)
select museum_id, language, museum_name, location, text_credit, categories
from jsonb_populate_recordset(null::public.catalogs, ${jsonb(catalog)})
on conflict (museum_id, language) do update set
  museum_name = excluded.museum_name, location = excluded.location,
  text_credit = excluded.text_credit, categories = excluded.categories;

-- Works that were removed from the data are removed from the table too.
delete from public.works where museum_id = '${museumId}' and language = '${language}'
  and id not in (select jsonb_array_elements_text(${jsonb(works.map((w) => w.id))}));
`;
    // The Supabase SQL editor rejects very large queries, so a big catalog is written as several files.
    const chunks = [];
    let current = [];
    let size = 0;
    for (const w of works) {
      const len = JSON.stringify(w).length;
      if (current.length && size + len > CHUNK_BYTES) {
        chunks.push(current);
        current = [];
        size = 0;
      }
      current.push(w);
      size += len;
    }
    if (current.length) chunks.push(current);
    for (const chunk of chunks) {
      parts.push(`
insert into public.works (museum_id, language, id, position, title, category, subtitle, artist, facts, object_url, image, guide)
select museum_id, language, id, position, title, category, subtitle, artist, facts, object_url, image, guide
from jsonb_populate_recordset(null::public.works, ${jsonb(chunk)})
on conflict (museum_id, language, id) do update set
  position = excluded.position, title = excluded.title, category = excluded.category,
  subtitle = excluded.subtitle, artist = excluded.artist, facts = excluded.facts,
  object_url = excluded.object_url, image = excluded.image, guide = excluded.guide;
`);
    }
  }
  // One file normally; a catalog over the limit is split into <name>-1.sql, <name>-2.sql, ... to run in order.
  const all = [sql, ...parts];
  const bytes = all.join("").length;
  if (bytes <= SPLIT_ABOVE) {
    writeFileSync(join(seedDir, `${entry.name}.sql`), header + all.join(""));
  } else {
    const files = [];
    let cur = sql;
    for (const part of parts) {
      if (cur.length + part.length > CHUNK_BYTES * 1.3 && cur.trim() && cur !== sql) {
        files.push(cur);
        cur = "";
      }
      cur += part;
    }
    files.push(cur);
    files.forEach((body, i) =>
      writeFileSync(join(seedDir, `${entry.name}-${i + 1}.sql`), `${header}-- Part ${i + 1} of ${files.length}: run the parts in order.\n${body}`),
    );
  }
}

console.log(`${museums.length} museums, ${total} works -> supabase/seed/`);
